[patterns/application/micro-frontend/PTN-APP-MFE-012-backend-api-integration-pattern.md#variation-1-paginated-infinite-scroll]

#### Variation 1: Paginated Infinite Scroll

Use `useInfiniteQuery` for infinite scroll lists (claims, providers, eligibility history).

**When to Use:**
- Large datasets (1000+ items)
- User scrolls to load more (not clicking "Next Page")
- Social media-style feeds

**Implementation:**

```typescript
// claims-mfe/src/hooks/useInfiniteClaims.ts
import { useInfiniteQuery } from '@tanstack/react-query';

export function useInfiniteClaims(memberId: string) {
  return useInfiniteQuery({
    queryKey: ['claims', memberId, 'infinite'],
    queryFn: ({ pageParam = 1 }) =>
      claimsAPIClient.getClaims({ memberId, page: pageParam, pageSize: 20 }),

    getNextPageParam: (lastPage) => {
      const { page, totalPages } = lastPage.pagination;
      return page < totalPages ? page + 1 : undefined;
    },
  });
}

// Component usage
function ClaimsList({ memberId }) {
  const { data, fetchNextPage, hasNextPage, isFetchingNextPage } = useInfiniteClaims(memberId);

  return (
    <div>
      {data.pages.map((page) =>
        page.data.map((claim) => <ClaimItem key={claim.id} claim={claim} />)
      )}

      {hasNextPage && (
        <button onClick={() => fetchNextPage()} disabled={isFetchingNextPage}>
          {isFetchingNextPage ? 'Loading...' : 'Load More'}
        </button>
      )}
    </div>
  );
}
```

**Trade-offs:**
- **Better UX**: No page navigation; seamless scrolling
- **Memory**: All loaded pages stay in memory (can grow large)
- **Complexity**: Must handle page boundaries, duplicate detection

