#### Step 1: Configure React Query in Shell

```typescript
// shell/src/App.tsx
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { ReactQueryDevtools } from '@tanstack/react-query-devtools';

// Create React Query client
const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      // Stale data refetched after 5 minutes
      staleTime: 5 * 60 * 1000,

      // Cached data kept for 30 minutes (even if component unmounts)
      cacheTime: 30 * 60 * 1000,

      // Refetch on window focus
      refetchOnWindowFocus: true,

      // Retry failed requests 3 times with exponential backoff
      retry: 3,
      retryDelay: (attemptIndex) => Math.min(1000 * 2 ** attemptIndex, 30000),

      // Use network cache first (browser HTTP cache)
      networkMode: 'online',
    },
    mutations: {
      // Retry mutations on failure
      retry: 1,
    },
  },
});

export function App() {
  return (
    <QueryClientProvider client={queryClient}>
      {/* All micro-frontends now have access to React Query */}
      <Routes>
        <Route path="/claims/*" element={<ClaimsMfe />} />
        <Route path="/eligibility/*" element={<EligibilityMfe />} />
      </Routes>

      {/* React Query DevTools (development only) */}
      {process.env.NODE_ENV === 'development' && <ReactQueryDevtools />}
    </QueryClientProvider>
  );
}
```

**Provide HTTP Client to Modules:**

```typescript
// shell/src/contexts/MfeContext.ts
export interface MfeContext {
  user: User;
  config: AppConfig;
  // Authenticated HTTP client
  httpClient: {
    get: <T>(url: string) => Promise<T>;
    post: <T>(url: string, data: any) => Promise<T>;
    put: <T>(url: string, data: any) => Promise<T>;
    delete: <T>(url: string) => Promise<T>;
  };
}
```

```typescript
// shell/src/services/httpClient.ts
export function createHttpClient(apiBaseUrl: string): MfeContext['httpClient'] {
  async function request<T>(url: string, options: RequestInit = {}): Promise<T> {
    const response = await fetch(`${apiBaseUrl}${url}`, {
      ...options,
      credentials: 'include',  // Send auth cookies
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });

    if (!response.ok) {
      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
    }

    return response.json();
  }

  return {
    get: <T>(url: string) => request<T>(url, { method: 'GET' }),
    post: <T>(url: string, data: any) => request<T>(url, { method: 'POST', body: JSON.stringify(data) }),
    put: <T>(url: string, data: any) => request<T>(url, { method: 'PUT', body: JSON.stringify(data) }),
    delete: <T>(url: string) => request<T>(url, { method: 'DELETE' }),
  };
}
```

