[patterns/application/micro-frontend/PTN-APP-MFE-012-backend-api-integration-pattern.md#step-2-implement-query-hooks-in-module]

#### Step 2: Implement Query Hooks in Module

```typescript
// claims-mfe/src/hooks/useClaimsQuery.ts
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { MfeContext } from '@gainwell/mfe-types';

export interface Claim {
  id: string;
  claimNumber: string;
  memberId: string;
  providerId: string;
  status: 'PENDING' | 'APPROVED' | 'DENIED';
  totalAmount: number;
  submittedAt: string;
}

export interface ClaimsListParams {
  memberId?: string;
  status?: string;
  page?: number;
  pageSize?: number;
}

/**

 * Fetch claims list with pagination
 */
export function useClaimsQuery(params: ClaimsListParams, context: MfeContext) {
  return useQuery({
    // Query key for caching (includes params for cache segmentation)
    queryKey: ['claims', params],

    // Query function
    queryFn: async () => {
      const query = new URLSearchParams({
        ...(params.memberId && { memberId: params.memberId }),
        ...(params.status && { status: params.status }),
        page: String(params.page || 1),
        pageSize: String(params.pageSize || 20),
      });

      const response = await context.httpClient.get<{
        claims: Claim[];
        total: number;
        page: number;
        pageSize: number;
      }>(`/claims?${query}`);

      return response;
    },

    // Keep data fresh for 5 minutes
    staleTime: 5 * 60 * 1000,

    // Enable query only if memberId provided
    enabled: !!params.memberId,
  });
}

/**

 * Fetch single claim detail
 */
export function useClaimQuery(claimId: string, context: MfeContext) {
  return useQuery({
    queryKey: ['claims', claimId],
    queryFn: () => context.httpClient.get<Claim>(`/claims/${claimId}`),
    staleTime: 5 * 60 * 1000,
    enabled: !!claimId,
  });
}

/**

 * Submit claim mutation with optimistic update
 */
export function useSubmitClaimMutation(context: MfeContext) {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (claimData: Partial<Claim>) => {
      return context.httpClient.post<Claim>('/claims', claimData);
    },

    // Optimistic update: immediately show claim in UI
    onMutate: async (claimData) => {
      // Cancel ongoing claims list queries
      await queryClient.cancelQueries({ queryKey: ['claims'] });

      // Snapshot previous claims for rollback
      const previousClaims = queryClient.getQueryData(['claims']);

      // Optimistically add new claim to cache
      queryClient.setQueryData(['claims'], (old: any) => ({
        ...old,
        claims: [
          {
            id: 'temp-' + Date.now(),  // Temporary ID
            ...claimData,
            status: 'PENDING',
            submittedAt: new Date().toISOString(),
          },
          ...(old?.claims || []),
        ],
      }));

      return { previousClaims };
    },

    // Rollback on error
    onError: (error, claimData, context) => {
      if (context?.previousClaims) {
        queryClient.setQueryData(['claims'], context.previousClaims);
      }
    },

    // Refetch on success to get backend-assigned ID
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['claims'] });
    },
  });
}
```

