[patterns/application/micro-frontend/PTN-APP-MFE-012-backend-api-integration-pattern.md#step-4-cache-invalidation-from-backend-events]

#### Step 4: Cache Invalidation from Backend Events

**Subscribe to EventBridge Events:**

```typescript
// shell/src/services/eventSubscription.ts
import { useQueryClient } from '@tanstack/react-query';
import { useEffect } from 'react';

export function useBackendEventSubscription() {
  const queryClient = useQueryClient();

  useEffect(() => {
    // Option 1: Server-Sent Events (SSE)
    const eventSource = new EventSource('/api/events', {
      withCredentials: true,
    });

    eventSource.addEventListener('claim.adjudicated', (event) => {
      const { claimId } = JSON.parse(event.data);

      // Invalidate specific claim cache
      queryClient.invalidateQueries({ queryKey: ['claims', claimId] });

      // Invalidate claims list cache (to update status in list)
      queryClient.invalidateQueries({ queryKey: ['claims'], exact: false });

      console.log(`[EventSubscription] Invalidated cache for claim ${claimId}`);
    });

    eventSource.addEventListener('member.eligibility.changed', (event) => {
      const { memberId } = JSON.parse(event.data);

      // Invalidate member cache
      queryClient.invalidateQueries({ queryKey: ['members', memberId] });

      console.log(`[EventSubscription] Invalidated cache for member ${memberId}`);
    });

    return () => {
      eventSource.close();
    };
  }, [queryClient]);
}
```

**Alternative: Polling Backend Events:**

```typescript
// If SSE not available, poll for events

export function useBackendEventPolling() {
  const queryClient = useQueryClient();

  useEffect(() => {
    let lastEventId: string | null = null;

    const poll = async () => {
      try {
        const response = await fetch(`/api/events?since=${lastEventId || ''}`, {
          credentials: 'include',
        });

        const events = await response.json();

        events.forEach((event: any) => {
          if (event.type === 'claim.adjudicated') {
            queryClient.invalidateQueries({ queryKey: ['claims', event.claimId] });
          }

          if (event.type === 'member.eligibility.changed') {
            queryClient.invalidateQueries({ queryKey: ['members', event.memberId] });
          }

          lastEventId = event.id;
        });
      } catch (error) {
        console.error('[EventPolling] Failed to fetch events:', error);
      }
    };

    // Poll every 10 seconds
    const interval = setInterval(poll, 10000);

    // Initial poll
    poll();

    return () => {
      clearInterval(interval);
    };
  }, [queryClient]);
}
```

**Use in Shell:**

```typescript
// shell/src/App.tsx
import { useBackendEventSubscription } from './services/eventSubscription';

export function App() {
  // Subscribe to backend events for cache invalidation
  useBackendEventSubscription();

  return <Routes>...</Routes>;
}
