#### Phase 2: React Query Setup (Weeks 2-3)

**2.1 Configure React Query Provider**

```typescript
// shell/src/App.tsx
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { ReactQueryDevtools } from '@tanstack/react-query-devtools';

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 5 * 60 * 1000, // Data considered fresh for 5 minutes
      cacheTime: 10 * 60 * 1000, // Cache persists for 10 minutes
      retry: 3, // Retry failed requests 3 times
      refetchOnWindowFocus: false, // Don't refetch on window focus (performance)
    },
    mutations: {
      retry: 1, // Retry failed mutations once
    },
  },
});

export function App() {
  return (
    <QueryClientProvider client={queryClient}>
      {/* Application content */}
      <ReactQueryDevtools initialIsOpen={false} />
    </QueryClientProvider>
  );
}
```

**2.2 Implement API Client**

```typescript
// shared-lib/src/api/clients/ClaimsAPIClient.ts
import { ClaimsAPI, Claim, PaginatedResponse } from '../contracts/ClaimsAPI';

const API_BASE_URL = process.env.REACT_APP_API_BASE_URL;

async function fetchWithAuth<T>(url: string, options?: RequestInit): Promise<T> {
  const token = await getAuthToken(); // Get JWT token from auth service

  const response = await fetch(`${API_BASE_URL}${url}`, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token}`,
      'X-Correlation-ID': crypto.randomUUID(), // For request tracing
      ...options?.headers,
    },
  });

  if (response.status === 401) {
    // Token expired - refresh and retry
    await refreshAuthToken();
    return fetchWithAuth(url, options);
  }

  if (!response.ok) {
    const error = await response.json();
    throw new Error(error.message || 'API request failed');
  }

  return response.json();
}

export const claimsAPIClient: ClaimsAPI = {
  async getClaims(params) {
    const query = new URLSearchParams({
      memberId: params.memberId,
      page: String(params.page || 1),
      pageSize: String(params.pageSize || 20),
      ...(params.status && { status: params.status }),
    });

    return fetchWithAuth<PaginatedResponse<Claim>>(`/api/v1/claims?${query}`);
  },

  async getClaim(claimId) {
    return fetchWithAuth<Claim>(`/api/v1/claims/${claimId}`);
  },

  async updateClaimStatus(claimId, status) {
    return fetchWithAuth<Claim>(`/api/v1/claims/${claimId}/status`, {
      method: 'PUT',
      body: JSON.stringify({ status }),
    });
  },
};
```

