#### Phase 3: Module Integration (Weeks 4-5)

**3.1 Implement React Query Hooks**

```typescript
// claims-mfe/src/hooks/useClaims.ts
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { claimsAPIClient } from '@gainwell/shared-lib/api';

export function useClaims(memberId: string, page: number = 1) {
  return useQuery({
    queryKey: ['claims', memberId, page],
    queryFn: () => claimsAPIClient.getClaims({ memberId, page }),
    enabled: !!memberId, // Only fetch if memberId provided
  });
}

export function useClaim(claimId: string) {
  return useQuery({
    queryKey: ['claim', claimId],
    queryFn: () => claimsAPIClient.getClaim(claimId),
    enabled: !!claimId,
  });
}

export function useUpdateClaimStatus() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ claimId, status }: { claimId: string; status: string }) =>
      claimsAPIClient.updateClaimStatus(claimId, status as any),

    // Optimistic update
    onMutate: async ({ claimId, status }) => {
      // Cancel outgoing queries
      await queryClient.cancelQueries({ queryKey: ['claim', claimId] });

      // Snapshot previous value
      const previousClaim = queryClient.getQueryData(['claim', claimId]);

      // Optimistically update cache
      queryClient.setQueryData(['claim', claimId], (old: any) => ({
        ...old,
        status,
      }));

      return { previousClaim };
    },

    // Rollback on error
    onError: (err, { claimId }, context) => {
      queryClient.setQueryData(['claim', claimId], context?.previousClaim);
    },

    // Refetch on success
    onSuccess: (data, { claimId }) => {
      queryClient.invalidateQueries({ queryKey: ['claims'] }); // Invalidate claims list
      queryClient.setQueryData(['claim', claimId], data); // Update claim detail
    },
  });
}
```

**3.2 Implement Module Component**

```typescript
// claims-mfe/src/pages/ClaimsList.tsx
import { useClaims } from '../hooks/useClaims';

export function ClaimsList({ memberId }: { memberId: string }) {
  const { data, isLoading, error, refetch } = useClaims(memberId);

  if (isLoading) return <LoadingSpinner />;
  if (error) return <ErrorMessage error={error} onRetry={refetch} />;

  return (
    <div>
      <h1>Claims ({data.pagination.totalCount})</h1>
      <ul>
        {data.data.map((claim) => (
          <ClaimItem key={claim.id} claim={claim} />
        ))}
      </ul>
    </div>
  );
}
```

