return (
  <InfiniteScroll onLoadMore={fetchNextPage} hasMore={hasNextPage}>
    {data.pages.flatMap((page) =>
      page.claims.map((claim) => <ClaimRow key={claim.id} claim={claim} />)
    )}
  </InfiniteScroll>
);
```

