[patterns/application/micro-frontend/PTN-APP-MFE-012-backend-api-integration-pattern.md#before-manual-state-management-with-useeffect]

#### Before: Manual State Management with useEffect

**Problem:**
Each module manually fetches data using `useEffect` and `useState`, leading to code duplication, stale data, and no caching.

**Claims Module (Before):**

```typescript
// claims-mfe/src/pages/ClaimsList.tsx (BEFORE)
import { useState, useEffect } from 'react';

export function ClaimsList({ memberId }: { memberId: string }) {
  const [claims, setClaims] = useState<Claim[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    let cancelled = false;

    async function fetchClaims() {
      setLoading(true);
      setError(null);

      try {
        const token = await getAuthToken();
        const response = await fetch(`/api/claims?memberId=${memberId}`, {
          headers: { Authorization: `Bearer ${token}` },
        });

        if (!response.ok) {
          throw new Error('Failed to fetch claims');
        }

        const data = await response.json();

        if (!cancelled) {
          setClaims(data.claims);
          setLoading(false);
        }
      } catch (err) {
        if (!cancelled) {
          setError(err as Error);
          setLoading(false);
        }
      }
    }

    fetchClaims();

    return () => {
      cancelled = true; // Cleanup: prevent state update after unmount
    };
  }, [memberId]); // Re-fetch when memberId changes

  // User navigates to Claim Detail, then back to Claims List
  // Claims List doesn't refetch → shows stale data

  if (loading) return <LoadingSpinner />;
  if (error) return <ErrorMessage error={error} />;

  return (
    <ul>
      {claims.map((claim) => (
        <li key={claim.id}>
          {claim.claimNumber} - {claim.status}  {/* Stale status! */}
        </li>
      ))}
    </ul>
  );
}
```

**Issues:**
1. **Code Duplication**: Every module implements same fetch logic (50+ lines per module)
2. **No Caching**: Every navigation refetches data (even if already fetched 10 seconds ago)
3. **Stale Data**: Backend adjudicates claim → UI shows old status until manual refresh
4. **No Retry Logic**: Network error → user sees error (no automatic retry)
5. **Race Conditions**: Fast navigation → old fetch completes after new fetch → wrong data displayed
6. **Memory Leaks**: Forgot `cancelled` flag → setState after unmount → React warning

